'use strict';

// Community Precision Benchmark
//
// Audits the quality of peer communities generated by resolveCreatorPeerContext().
// Measures how many peers are genuinely relevant (language, region, topic, format).
// Identifies false positives and explains their root causes.
//
// Usage:
//   node server/scripts/communityPrecisionBenchmark.js
//   node server/scripts/communityPrecisionBenchmark.js --channel="Jimmy Fallon"
//   node server/scripts/communityPrecisionBenchmark.js --sample=100
//   node server/scripts/communityPrecisionBenchmark.js --channel="Jimmy Fallon" --top=40

require('dotenv').config({ path: __dirname + '/../.env' });

const path         = require('path');
const BetterSqlite = require('../node_modules/better-sqlite3');
const { resolveCreatorPeerContext, buildPeersByContent } = require('../services/creatorPeerContext');

// ── CLI args ──────────────────────────────────────────────────────────────────
const args = Object.fromEntries(
  process.argv.slice(2)
    .filter(a => a.startsWith('--'))
    .map(a => {
      const [k, v] = a.slice(2).split('=');
      return [k, v === undefined ? true : isNaN(v) ? v : Number(v)];
    }),
);
const FILTER   = args.channel ? String(args.channel).toLowerCase() : null;
const SAMPLE   = Math.max(0, Number(args.sample) || 0);
const TOP_SHOW = Math.max(5, Math.min(60, Number(args.top) || 25));

// ── DB ────────────────────────────────────────────────────────────────────────
function openDb() {
  const raw = new BetterSqlite(path.resolve(__dirname, '../data/scoring.db'), {
    readonly: false, fileMustExist: true, timeout: 60_000,
  });
  raw.pragma('journal_mode=WAL');
  raw.pragma('busy_timeout=60000');
  raw.pragma('synchronous=NORMAL');
  const stmtCache = new Map();
  const stmt = sql => {
    if (!stmtCache.has(sql)) stmtCache.set(sql, raw.prepare(sql));
    return stmtCache.get(sql);
  };
  return {
    all:         (sql, p = []) => stmt(sql).all(Array.isArray(p) ? p : [p]),
    get:         (sql, p = []) => stmt(sql).get(Array.isArray(p) ? p : [p]),
    run:         (sql, p = []) => stmt(sql).run(Array.isArray(p) ? p : [p]),
    transaction: fn => raw.transaction(fn),
    close:       () => { stmtCache.clear(); raw.close(); },
  };
}

// ── Niche clusters (mirrors NICHE_CLUSTERS in creatorPeerContext.js) ──────────
const NICHE_CLUSTERS = {
  comedy:              ['comedy', 'entertainment', 'comedy sketches'],
  'comedy sketches':   ['comedy', 'entertainment', 'comedy sketches'],
  entertainment:       ['comedy', 'entertainment', 'comedy sketches'],
  finance:             ['finance', 'personal finance', 'investing', 'stock market', 'cryptocurrency'],
  'personal finance':  ['finance', 'personal finance', 'investing', 'stock market', 'cryptocurrency'],
  investing:           ['finance', 'personal finance', 'investing', 'stock market', 'cryptocurrency'],
  'stock market':      ['finance', 'personal finance', 'investing', 'stock market', 'cryptocurrency'],
  selfimprovement:     ['selfimprovement', 'motivation', 'personal development', 'personal growth', 'mindset'],
  motivation:          ['selfimprovement', 'motivation', 'personal development', 'personal growth', 'mindset'],
  'personal development': ['selfimprovement', 'motivation', 'personal development', 'personal growth', 'mindset'],
  'personal growth':   ['selfimprovement', 'motivation', 'personal development', 'personal growth', 'mindset'],
  fitness:             ['fitness', 'workout', 'bodybuilding', 'strength training', 'muscle building', 'gym workouts'],
  workout:             ['fitness', 'workout', 'bodybuilding', 'strength training', 'gym workouts'],
  bodybuilding:        ['fitness', 'bodybuilding', 'workout', 'strength training', 'muscle building'],
  yoga:                ['yoga', 'somatic yoga', 'yoga practice', 'meditation'],
  meditation:          ['meditation', 'mindfulness', 'yoga', 'sleep meditation'],
  business:            ['business', 'entrepreneurship', 'startup'],
  entrepreneurship:    ['business', 'entrepreneurship', 'startup'],
  startup:             ['business', 'entrepreneurship', 'startup'],
  news:                ['news', 'current affairs', 'breaking news'],
  'current affairs':   ['news', 'current affairs', 'breaking news'],
  food:                ['food', 'street food', 'cooking'],
  cooking:             ['food', 'street food', 'cooking'],
  'street food':       ['food', 'street food', 'cooking'],
  travel:              ['travel', 'travel vlogs'],
  'travel vlogs':      ['travel', 'travel vlogs'],
  lifestyle:           ['lifestyle', 'daily vlogs', 'daily life vlogs', 'personal vlogs', 'vlog'],
  vlog:                ['lifestyle', 'daily vlogs', 'daily life vlogs', 'personal vlogs', 'vlog'],
  'daily vlogs':       ['lifestyle', 'daily vlogs', 'daily life vlogs', 'personal vlogs', 'vlog'],
};

function getCluster(niche) {
  const key = (niche || '').toLowerCase();
  return new Set(NICHE_CLUSTERS[key] || [key]);
}

// ── Region constants ──────────────────────────────────────────────────────────
const EN_REGIONS = new Set(['EN', 'US', 'GB', 'AU', 'CA', 'NZ', 'IE']);

// ── Phrase parsing ────────────────────────────────────────────────────────────
function parsePhrases(raw) {
  if (!raw) return [];
  try {
    const arr = JSON.parse(raw);
    if (Array.isArray(arr))
      return arr.map(e => (typeof e === 'object' ? (e.phrase || '') : String(e))).filter(Boolean);
  } catch (_) {}
  return raw.split('|').map(s => s.trim()).filter(Boolean);
}

function jaccardSim(a, b) {
  const sa = new Set(a);
  const sb = new Set(b);
  let shared = 0;
  for (const p of sa) if (sb.has(p)) shared++;
  const union = sa.size + sb.size - shared;
  return union > 0 ? +(shared / union).toFixed(4) : 0;
}

function sharedPhrases(a, b) {
  const sb = new Set(b);
  return a.filter(p => sb.has(p));
}

// ── Overlap metrics ───────────────────────────────────────────────────────────
//
// topic_relevant   — peer's niche is within the creator's niche cluster
// format_relevant  — peer's format_type matches creator's (null = unknown)
// language_relevant— peer's primary_language matches creator's (null = unknown)
// region_relevant  — peer is in the same region group (EN vs IN vs other)
// audience_relevant— peer's subscriber count is within a 0.05× – 100× ratio
// phrase_sim       — Jaccard similarity of content fingerprint phrases (0-1)
// guest_sim        — shared fingerprint phrases as a proxy for shared topic/guest signals
//
// is_false_positive — TRUE when we can confirm the peer is a language/region mismatch:
//   • peer has explicit primary_language != creator language
//   • OR peer is confirmed IN region while creator is confirmed EN/US/etc.
//   • AND this isn't just a null-language ambiguity

function measureOverlap(creator, peer) {
  const creatorLang   = creator.primary_language || null;
  const peerLang      = peer.primary_language    || null;
  const creatorRegion = creator.region           || null;
  const peerRegion    = peer.region              || null;

  // Language
  const lang_relevant =
    (!creatorLang || !peerLang) ? null :                       // unknown
    (creatorLang === peerLang)  ? 1    : 0;

  // Region
  const creatorIsEN = EN_REGIONS.has(creatorRegion);
  const peerIsEN    = EN_REGIONS.has(peerRegion);
  const peerIsIN    = peerRegion === 'IN';
  const region_relevant =
    (!creatorRegion || !peerRegion) ? null :
    (creatorIsEN && peerIsEN)       ? 1 :
    (creatorRegion === 'IN' && peerIsIN) ? 1 : 0;

  // Topic
  const creatorCluster = getCluster(creator.niche);
  const peerNiche      = (peer.niche || '').toLowerCase();
  const topic_relevant = creatorCluster.has(peerNiche) ? 1 : 0;

  // Format
  const cf = creator.format_type;
  const pf = peer.format_type;
  const format_relevant =
    (!cf || !pf || cf === 'other' || pf === 'other') ? null :
    (cf === pf) ? 1 : 0;

  // Audience (subscriber ratio)
  const ratio = creator.subs > 0 && peer.subs > 0 ? peer.subs / creator.subs : null;
  const audience_relevant =
    ratio === null ? null :
    (ratio > 100 || ratio < 0.01) ? 0 : 1;

  // Phrase similarity + shared phrases (proxy for guest/topic overlap)
  const creatorPhrases = parsePhrases(creator.fingerprint).slice(0, 15);
  const peerPhrases    = parsePhrases(peer.fingerprint).slice(0, 15);
  const phrase_sim     = jaccardSim(creatorPhrases, peerPhrases);
  const shared         = sharedPhrases(creatorPhrases, peerPhrases);

  // False positive determination
  // Confirmed FP: language explicitly different, OR confirmed cross-region (IN vs EN)
  const explicit_lang_mismatch  = (lang_relevant === 0);
  const confirmed_region_mismatch =
    region_relevant === 0 &&
    creatorRegion !== null && peerRegion !== null;  // both known
  // Partial FP: EN creator with IN-region peer (even if language unknown)
  const en_in_mismatch = creatorIsEN && peerIsIN;

  const is_false_positive =
    explicit_lang_mismatch ||
    confirmed_region_mismatch ||
    en_in_mismatch;

  // Root cause for display
  const fp_reasons = [];
  if (explicit_lang_mismatch)    fp_reasons.push(`lang(${peerLang}≠${creatorLang})`);
  if (en_in_mismatch && !explicit_lang_mismatch) fp_reasons.push(`region(IN→EN pool)`);
  if (confirmed_region_mismatch && !en_in_mismatch && !explicit_lang_mismatch)
    fp_reasons.push(`region(${peerRegion}≠${creatorRegion})`);

  // Admission route — where in the pipeline this peer was likely admitted
  let admission_gap = null;
  if (is_false_positive) {
    if (!peerLang && peerIsIN) {
      admission_gap = 'NULL_LANG_IN_REGION';  // IN-region but no language tag
    } else if (!peerLang && !peerRegion) {
      admission_gap = 'NULL_LANG_NULL_REGION'; // no metadata at all → slips past both filters
    } else if (peerLang && peerLang !== 'en' && creatorLang === 'en') {
      admission_gap = 'EXPLICIT_LANG_MISMATCH_SLIPPED_TIER3'; // Tier 3 has no lang filter
    } else if (en_in_mismatch) {
      admission_gap = 'IN_REGION_NO_FILTER_IN_TIER3'; // Tier 3 content-first has no region filter
    }
  }

  return {
    lang_relevant, region_relevant, topic_relevant, format_relevant,
    audience_relevant, phrase_sim, shared_phrases: shared,
    is_false_positive, fp_reasons, admission_gap,
  };
}

// ── Formatting helpers ────────────────────────────────────────────────────────
function pad(s, n) { return String(s || '').padEnd(n).slice(0, n); }
function rpad(s, n) { return String(s || '').padStart(n).slice(-n); }

function bool3(v, label = '') {
  if (v === null || v === undefined) return '\x1b[2m—\x1b[0m ';
  if (v === 1) return '\x1b[32m✓\x1b[0m ';
  return label ? `\x1b[31m✗\x1b[0m ` : '\x1b[31m✗\x1b[0m ';
}

function fmtSubs(n) {
  if (!n || n < 1) return '—';
  if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(0) + 'K';
  return String(n);
}

function pct(v) {
  if (v === null || v === undefined) return '—';
  return (v * 100).toFixed(0) + '%';
}

function avg(arr) {
  const valid = arr.filter(v => v !== null && v !== undefined);
  return valid.length ? valid.reduce((s, v) => s + v, 0) / valid.length : null;
}

function printDivider(c = '─', w = 128) { console.log('  ' + c.repeat(w)); }

// ── Core: audit one channel ───────────────────────────────────────────────────
function auditChannel(db, channelRow) {
  const ctx = resolveCreatorPeerContext(db, channelRow.channel_id, {
    debug: true,
    userSubs: channelRow.channel_subscribers || 0,
  });

  const peerIds = ctx.peerIds || [];
  if (!peerIds.length) {
    return { channel: channelRow, ctx, peerCount: 0, peers: [], stats: null };
  }

  // Fetch peer metadata
  const ph      = peerIds.map(() => '?').join(',');
  const peerRows = db.all(
    `SELECT channel_id, channel_name,
            COALESCE(primary_niche, niche) AS niche,
            format_type, content_archetype, primary_language, region,
            channel_subscribers, content_fingerprint
     FROM ingested_channels WHERE channel_id IN (${ph})`,
    peerIds,
  );
  const peerMap = new Map(peerRows.map(r => [r.channel_id, r]));

  // Score breakdown from the debug output (only top 20 from buildPeersByContent)
  const breakdownMap = new Map();
  for (const b of (ctx.peer_routing_debug?.peerBreakdown || [])) {
    breakdownMap.set(b.channel_id, b);
  }

  const creator = {
    niche:            channelRow.primary_niche || channelRow.niche,
    format_type:      channelRow.format_type,
    subs:             channelRow.channel_subscribers || 0,
    primary_language: channelRow.primary_language,
    region:           channelRow.region,
    fingerprint:      channelRow.content_fingerprint,
  };

  const peers = [];
  for (const id of peerIds.slice(0, 200)) {
    const p = peerMap.get(id);
    if (!p) continue;
    const overlap = measureOverlap(creator, {
      niche:            p.niche,
      format_type:      p.format_type,
      subs:             p.channel_subscribers || 0,
      primary_language: p.primary_language,
      region:           p.region,
      fingerprint:      p.content_fingerprint,
    });
    peers.push({ ...p, overlap, peerScore: breakdownMap.get(id) || null });
  }

  const total          = peers.length;
  const fpCount        = peers.filter(p => p.overlap.is_false_positive).length;
  const langKnown      = peers.filter(p => p.overlap.lang_relevant !== null);
  const regionKnown    = peers.filter(p => p.overlap.region_relevant !== null);
  const formatKnown    = peers.filter(p => p.overlap.format_relevant !== null);
  const audKnown       = peers.filter(p => p.overlap.audience_relevant !== null);
  const topicMatch     = peers.filter(p => p.overlap.topic_relevant === 1).length;

  const stats = total > 0 ? {
    precision:  (total - fpCount) / total,
    lang:       langKnown.length   ? langKnown.filter(p => p.overlap.lang_relevant === 1).length / langKnown.length : null,
    region:     regionKnown.length ? regionKnown.filter(p => p.overlap.region_relevant === 1).length / regionKnown.length : null,
    topic:      topicMatch / total,
    format:     formatKnown.length ? formatKnown.filter(p => p.overlap.format_relevant === 1).length / formatKnown.length : null,
    audience:   audKnown.length    ? audKnown.filter(p => p.overlap.audience_relevant === 1).length / audKnown.length : null,
    avg_phrase: avg(peers.map(p => p.overlap.phrase_sim)),
  } : null;

  return { channel: channelRow, ctx, peerCount: total, peers, fpCount, stats };
}

// ── Print: deep dive for one channel ─────────────────────────────────────────
function printChannelAudit(result, topN) {
  const { channel, ctx, peerCount, peers, fpCount, stats } = result;

  printDivider('═');
  console.log(`  CHANNEL: ${channel.channel_name}  (${channel.channel_id})`);
  console.log(`  Niche: ${channel.primary_niche || channel.niche || '—'}  |  Format: ${channel.format_type || '—'}  |  Lang: ${channel.primary_language || '—'}  |  Region: ${channel.region || '—'}  |  Subs: ${fmtSubs(channel.channel_subscribers)}`);
  console.log(`  Peer source: \x1b[1m${ctx.peer_source}\x1b[0m  |  Pool size: ${peerCount}  |  False positives: \x1b[${fpCount > 0 ? '31' : '32'}m${fpCount}\x1b[0m/${peerCount} (${pct(peerCount > 0 ? fpCount / peerCount : 0)})`);

  // Routing path summary
  const routing = ctx.peer_routing_debug;
  if (routing) {
    console.log(`  Routing mode: ${routing.routing_mode || '—'}  |  Peer failure reason: ${routing.peer_failure_reason || 'none'}`);
    console.log(`  User classification: niche=${routing.user_classification?.niche || '—'}  format=${routing.user_classification?.format_type || '—'}  archetype=${routing.user_classification?.content_archetype || '—'}  lang=${routing.user_classification?.primary_language || '—'}`);
    if (routing.weights) {
      const w = routing.weights;
      console.log(`  Peer score weights: topic=${w.topic} format=${w.format} style=${w.style} lang=${w.language} phrase=${w.phrase}`);
    }
  }

  if (stats) {
    console.log(`\n  PRECISION BREAKDOWN:`);
    console.log(`    Overall (non-FP):   ${pct(stats.precision)}  ← fraction of peers that are relevant`);
    console.log(`    Language match:     ${pct(stats.lang)}        ← peers with matching primary_language (of those where known)`);
    console.log(`    Region match:       ${pct(stats.region)}       ← peers in same region group (EN/IN/etc.)`);
    console.log(`    Topic match:        ${pct(stats.topic)}        ← peers within same niche cluster`);
    console.log(`    Format match:       ${pct(stats.format)}       ← peers with same format_type`);
    console.log(`    Audience match:     ${pct(stats.audience)}     ← peers with subs within 0.01–100× ratio`);
    console.log(`    Avg phrase sim:     ${stats.avg_phrase !== null ? stats.avg_phrase.toFixed(3) : '—'} ← Jaccard similarity of content fingerprints`);
  }

  // Peer table
  console.log(`\n  PEER LIST  (top ${Math.min(topN, peerCount)} of ${peerCount}):`);
  console.log(
    `  ${'#'.padEnd(4)} ${pad('Channel', 34)} ${pad('Niche', 18)} ${'Lang'.padEnd(5)} ${'Reg'.padEnd(5)} ${rpad('Subs', 7)}  ${'PSim'.padEnd(5)} ${'Lang'.padEnd(5)} ${'Rgn'.padEnd(5)} ${'Top'.padEnd(5)} ${'Fmt'.padEnd(5)} ${'Aud'.padEnd(5)} ${'FP?'}`
  );
  printDivider('·', 127);

  peers.slice(0, topN).forEach((p, i) => {
    const o = p.overlap;
    const fp = o.is_false_positive ? `\x1b[31m← ${o.fp_reasons.join(' ')}\x1b[0m` : '';
    const pSim = o.phrase_sim.toFixed(2).padStart(4);
    console.log(
      `  ${String(i + 1).padStart(3)} ` +
      `${pad(p.channel_name, 34)} ` +
      `${pad(p.niche, 18)} ` +
      `${pad(p.primary_language || '—', 5)} ` +
      `${pad(p.region || '—', 5)} ` +
      `${rpad(fmtSubs(p.channel_subscribers), 7)}  ` +
      `${pSim.padEnd(5)} ` +
      `${bool3(o.lang_relevant)}    ${bool3(o.region_relevant)}    ${bool3(o.topic_relevant)}    ${bool3(o.format_relevant)}    ${bool3(o.audience_relevant)}  ` +
      `${fp}`
    );

    // Show per-peer score breakdown if available
    if (p.peerScore) {
      const b = p.peerScore;
      const scoreStr = `topic=${b.topic_match ?? '?'} fmt=${b.format_match ?? '?'} style=${b.style_match ?? '?'} lang=${b.language_match ?? '?'} phraseSim=${b.phrase_similarity ?? '?'} → ${b.final_score ?? '?'}`;
      console.log(`  \x1b[2m          Score breakdown: ${scoreStr}\x1b[0m`);
    }

    // Show shared phrases for false positives
    if (o.is_false_positive && o.shared_phrases.length > 0) {
      console.log(`  \x1b[33m          Shared phrases causing admission: ${o.shared_phrases.slice(0, 6).map(p => `"${p}"`).join(', ')}\x1b[0m`);
    }
  });

  // False positive analysis
  const fps = peers.filter(p => p.overlap.is_false_positive);
  if (fps.length > 0) {
    console.log(`\n  FALSE POSITIVES — admission gap analysis:`);
    const gapCounts = {};
    for (const p of fps) {
      const gap = p.overlap.admission_gap || 'UNKNOWN';
      gapCounts[gap] = (gapCounts[gap] || 0) + 1;
    }
    for (const [gap, count] of Object.entries(gapCounts).sort((a, b) => b[1] - a[1])) {
      const desc = {
        NULL_LANG_NULL_REGION:              'No primary_language and no region tag — survives all filters',
        NULL_LANG_IN_REGION:                'IN-region channel with NULL primary_language — survives Tier 3 (no region filter) and language script check if titles are Latin',
        EXPLICIT_LANG_MISMATCH_SLIPPED_TIER3: 'Non-EN language, but Tier 3 (buildPeersByContent) has no language filter — admitted before language gate',
        IN_REGION_NO_FILTER_IN_TIER3:       'IN-region channel — Tier 3 phrase matching has no region filter; region filter (rc) only applies to expansion tiers',
      }[gap] || 'Unknown admission path';
      console.log(`    [${gap}] ×${count}  ${desc}`);
    }

    console.log(`\n  Per false positive:`);
    for (const p of fps.slice(0, 15)) {
      const o = p.overlap;
      const shared = o.shared_phrases.slice(0, 5).map(s => `"${s}"`).join(', ');
      console.log(`    × ${pad(p.channel_name, 32)} ${pad(p.primary_language || 'lang?', 6)} ${pad(p.region || 'reg?', 6)} — ${o.fp_reasons.join(', ')}${shared ? ` | shared: ${shared}` : ''}`);
    }
  }
  console.log('');
}

// ── Benchmark channels ────────────────────────────────────────────────────────
const BENCHMARK_CHANNELS = [
  { name: 'Jimmy Fallon',   search: '%fallon%',        expected_niche: 'entertainment', expected_lang: 'en', expected_region: 'US' },
  { name: 'Joe Rogan',      search: '%rogan%',          expected_niche: 'podcast',       expected_lang: 'en', expected_region: 'US' },
  { name: 'BeerBiceps',     search: '%beerbiceps%',     expected_niche: 'selfimprovement', expected_lang: 'en', expected_region: 'IN' },
  { name: 'Tech Burner',    search: '%tech burner%',    expected_niche: 'technology',    expected_lang: 'en', expected_region: 'IN' },
  { name: 'Aaj Tak',        search: '%aaj tak%',        expected_niche: 'news',          expected_lang: 'hi', expected_region: 'IN' },
  { name: 'Physics Wallah', search: '%physics wallah%', expected_niche: 'education',     expected_lang: 'hi', expected_region: 'IN' },
];

// ── Main ─────────────────────────────────────────────────────────────────────
const db = openDb();

const namedChannels = FILTER
  ? BENCHMARK_CHANNELS.filter(c => c.name.toLowerCase().includes(FILTER))
  : BENCHMARK_CHANNELS;

console.log('\n');
console.log('  ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════');
console.log('  COMMUNITY PRECISION BENCHMARK  —  ' + new Date().toISOString().slice(0, 16).replace('T', ' '));
console.log('  Measures: language + region + topic + format match rates per peer. Identifies false positives and admission gaps.');
console.log('  ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════');

const allResults = [];

for (const bench of namedChannels) {
  const channelRow = db.get(
    `SELECT channel_id, channel_name, primary_niche, niche, format_type,
            primary_language, region, channel_subscribers, content_fingerprint
     FROM ingested_channels
     WHERE channel_name LIKE ? ORDER BY channel_subscribers DESC LIMIT 1`,
    [bench.search],
  );
  if (!channelRow) {
    console.log(`\n  ⚠  ${bench.name} — not found (search: "${bench.search}") — skipping`);
    continue;
  }
  let result;
  try {
    result = auditChannel(db, channelRow);
  } catch (e) {
    console.log(`\n  ✗  ${bench.name} — error: ${e.message}`);
    continue;
  }
  printChannelAudit(result, TOP_SHOW);
  allResults.push({ bench, result });
}

// ── Named channel summary table ───────────────────────────────────────────────
if (allResults.length > 1) {
  printDivider('═');
  console.log('  NAMED CHANNEL SUMMARY');
  printDivider();
  console.log(
    `  ${'Channel'.padEnd(32)} ${'Peers'.padEnd(7)} ${'FP'.padEnd(5)} ${'Prec'.padEnd(6)} ${'Lang'.padEnd(6)} ${'Rgn'.padEnd(6)} ${'Topic'.padEnd(6)} ${'Fmt'.padEnd(6)} ${'Aud'.padEnd(6)} ${'PSim'.padEnd(6)} Source`
  );
  printDivider('·');
  for (const { bench, result } of allResults) {
    const { peerCount, fpCount, stats, ctx } = result;
    const s  = stats || {};
    const fp = fpCount > 0 ? `\x1b[31m${fpCount}\x1b[0m` : '0';
    console.log(
      `  ${pad(result.channel.channel_name, 32)} ` +
      `${String(peerCount).padEnd(7)} ` +
      `${fp.padEnd(14)} ` +
      `${pct(s.precision).padEnd(6)} ` +
      `${pct(s.lang).padEnd(6)} ` +
      `${pct(s.region).padEnd(6)} ` +
      `${pct(s.topic).padEnd(6)} ` +
      `${pct(s.format).padEnd(6)} ` +
      `${pct(s.audience).padEnd(6)} ` +
      `${s.avg_phrase !== null && s.avg_phrase !== undefined ? s.avg_phrase.toFixed(2).padEnd(6) : '—'.padEnd(6)} ` +
      `${ctx.peer_source}`
    );
  }
  console.log('');
}

// ── Aggregate sample benchmark ────────────────────────────────────────────────
if (SAMPLE > 0) {
  printDivider('═');
  console.log(`  AGGREGATE PRECISION BENCHMARK  —  ${SAMPLE} randomly sampled channels`);
  console.log('  (Excludes channels with 0 peers. Precision = fraction not classified as false positives.)');
  printDivider();

  const sampleRows = db.all(
    `SELECT channel_id, channel_name, primary_niche, niche, format_type,
            primary_language, region, channel_subscribers, content_fingerprint
     FROM ingested_channels
     WHERE ingest_enabled = 1
       AND (primary_niche IS NOT NULL OR niche IS NOT NULL)
     ORDER BY RANDOM() LIMIT ?`,
    [SAMPLE],
  );

  const agg = {
    precision: [], lang: [], region: [], topic: [], format: [], audience: [], phrase: [],
    fp_rate: [], total_peers: 0, channels_with_peers: 0, errors: 0,
    fp_gap_counts: {},
    niche_fp_counts: {},        // which niche categories produce most false positives
    peer_source_counts: {},
  };

  process.stdout.write('\n  Sampling');
  let done = 0;
  for (const row of sampleRows) {
    let result;
    try {
      result = auditChannel(db, row);
    } catch (_) {
      agg.errors++;
      done++;
      if (done % 10 === 0) process.stdout.write('.');
      continue;
    }
    done++;
    if (done % 10 === 0) process.stdout.write('.');

    if (!result.peerCount || !result.stats) continue;
    agg.channels_with_peers++;
    agg.total_peers += result.peerCount;

    const s = result.stats;
    if (s.precision  !== null) agg.precision.push(s.precision);
    if (s.lang       !== null) agg.lang.push(s.lang);
    if (s.region     !== null) agg.region.push(s.region);
    if (s.topic      !== null) agg.topic.push(s.topic);
    if (s.format     !== null) agg.format.push(s.format);
    if (s.audience   !== null) agg.audience.push(s.audience);
    if (s.avg_phrase !== null) agg.phrase.push(s.avg_phrase);
    agg.fp_rate.push(result.peerCount > 0 ? result.fpCount / result.peerCount : 0);

    // Aggregate admission gaps
    for (const p of result.peers) {
      if (p.overlap.is_false_positive && p.overlap.admission_gap) {
        const gap = p.overlap.admission_gap;
        agg.fp_gap_counts[gap] = (agg.fp_gap_counts[gap] || 0) + 1;
      }
    }

    // Track peer source distribution
    const src = result.ctx.peer_source || 'unknown';
    agg.peer_source_counts[src] = (agg.peer_source_counts[src] || 0) + 1;
  }
  process.stdout.write('\n\n');

  const avgFn = arr => avg(arr.filter(v => v !== null));

  console.log(`  Channels sampled:      ${sampleRows.length}  (${agg.errors} errors)`);
  console.log(`  Channels with peers:   ${agg.channels_with_peers}`);
  console.log(`  Total peers measured:  ${agg.total_peers}`);
  console.log(`  Avg peers / channel:   ${agg.channels_with_peers > 0 ? (agg.total_peers / agg.channels_with_peers).toFixed(1) : '—'}`);
  console.log('');
  console.log('  PRECISION METRICS  (averages across channels with peers):');
  console.log(`  Overall precision:         ${pct(avgFn(agg.precision))}  ← avg fraction of peers not classified as false positives`);
  console.log(`  Language match rate:        ${pct(avgFn(agg.lang))}  ← of peers where language is known on both sides`);
  console.log(`  Region match rate:          ${pct(avgFn(agg.region))}  ← of peers where region is known on both sides`);
  console.log(`  Topic (niche cluster):      ${pct(avgFn(agg.topic))}  ← peers within same niche cluster`);
  console.log(`  Format type match:          ${pct(avgFn(agg.format))}  ← of peers where format is known on both sides`);
  console.log(`  Audience size match:        ${pct(avgFn(agg.audience))}  ← peers with sub ratio 0.01-100×`);
  console.log(`  Avg phrase similarity:      ${avgFn(agg.phrase) !== null ? avgFn(agg.phrase).toFixed(3) : '—'}`);
  console.log(`  False positive rate:        ${pct(avgFn(agg.fp_rate))}  ← avg FP fraction per channel`);
  console.log('');
  console.log('  PEER SOURCE DISTRIBUTION:');
  for (const [src, count] of Object.entries(agg.peer_source_counts).sort((a, b) => b[1] - a[1])) {
    console.log(`    ${pad(src, 20)} ${count} channels  (${pct(count / agg.channels_with_peers)})`);
  }
  console.log('');
  if (Object.keys(agg.fp_gap_counts).length > 0) {
    console.log('  FALSE POSITIVE ADMISSION GAPS (across all sampled channels):');
    for (const [gap, count] of Object.entries(agg.fp_gap_counts).sort((a, b) => b[1] - a[1])) {
      console.log(`    ${pad(gap, 40)} ×${count}`);
    }
  }
}

// ── Recommendations ───────────────────────────────────────────────────────────
printDivider('═');
console.log('  IDENTIFIED ISSUES & RECOMMENDATIONS');
printDivider();
console.log(`
  ROOT CAUSE 0 — Niche misclassification breaks the entire peer + template pipeline
  ───────────────────────────────────────────────────────────────────────────────────
  Live result: The Tonight Show Starring Jimmy Fallon has niche=FINANCE in the DB.
  This is wrong — he is entertainment/comedy. This single misclassification causes:
    • Topic match: 3% (finance cluster ≠ entertainment)
    • originalBets: finance family templates applied → "How X can change your money decision"
    • WTP recommendations: peer pool built from finance channels, not entertainment

  The niche field is set by the channel ingestion/classification pipeline, not by this
  benchmark or WTP. This benchmark surfaces the classification as a measurable signal.

  FIX: The niche classification pipeline needs to correctly tag entertainment channels.
  As a guard in creatorPeerContext.js: if niche=finance but archetype=entertainer AND
  behavior_tags contain sketch/performance, override resolved_niche to entertainment/comedy.
  This prevents the finance peer pool from activating for entertainers.

  ───────────────────────────────────────────────────────────────────────────────────
  ROOT CAUSE 1 — Tier 3 (buildPeersByContent) has no language or region filter
  ─────────────────────────────────────────────────────────────────────────────
  The primary peer engine (phrase-based) queries content_fingerprint LIKE ?
  with no language/region constraint. Indian channels with Latin-script English
  titles match the same phrases as US channels ("show", "comedy", "celebrity",
  "interview"). The language gate runs AFTER the pool is built (line 1384).

  FIX: Add language and region pre-filters to the buildPeersByContent SQL query:
       WHERE content_fingerprint IS NOT NULL AND (<phrase conditions>)
         AND (primary_language = ? OR primary_language IS NULL)   ← add this
         AND channel_id != ? AND ingest_enabled = 1

  Impact: Blocks the admission of confirmed-non-English channels at query time,
  before scoring. Doesn't affect channels with NULL language (kept for fallback).

  ───────────────────────────────────────────────────────────────────────────────
  ROOT CAUSE 2 — NULL primary_language channels pass the language filter
  ─────────────────────────────────────────────────────────────────────────────
  The post-pool language filter (lines 1396-1417) checks null-language channels
  for Devanagari script. But channels like "Netflix India" or "The Kapil Sharma
  Show" often have Latin-script English titles → extractPhrases returns results
  → NOT flagged as Hindi → passes the filter despite being Indian content.

  FIX: For EN-creator pools, also check region='IN' for null-language channels.
  If a null-language channel has region='IN', require explicit primary_language='en'
  confirmation before including it in an EN-creator pool.

  Filter to add alongside the Devanagari check (lines 1396-1417):
    const regionInIds = poolRows
      .filter(r => !r.primary_language && r.region === 'IN')
      .map(r => r.channel_id);
    // Add regionInIds to hindiNullIds (or separately exclude unless confirmed EN).

  Impact: Eliminates Netflix India, Kapil Sharma from Jimmy Fallon's pool.
  Risk: May narrow pools for Indian-English creators — test against BeerBiceps.

  ───────────────────────────────────────────────────────────────────────────────
  ROOT CAUSE 3 — Language weight (0.10) is dominated by phrase similarity (0.50)
  ─────────────────────────────────────────────────────────────────────────────
  In computePeerScore(), a peer with high phrase similarity gets +0.50 bonus
  regardless of language. A language mismatch only costs 0.10. So even when the
  filter misses something, the scoring still promotes language-mismatched peers.

  FIX: Increase language weight to 0.20-0.25 AND apply a hard penalty multiplier
  for confirmed language mismatches:
    if (user.primary_language && peer.primary_language && user.primary_language !== peer.primary_language) {
      return { ...breakdown, score: breakdown.score * 0.3 }; // heavy penalty
    }

  Impact: Language-mismatched peers scored out of top positions even if phrase sim is high.

  ───────────────────────────────────────────────────────────────────────────────
  ROOT CAUSE 4 — Niche cluster combines comedy/entertainment without format guard
  ─────────────────────────────────────────────────────────────────────────────
  NICHE_CLUSTERS maps comedy → entertainment → comedy sketches as one cluster.
  This is correct for topic space, but "entertainment" in India and "entertainment"
  in the US are completely different content landscapes. The cluster broadens the
  pool before the format/language guards run.

  FIX: For Category B channels (entertainment, comedy), add a sub-cluster flag
  (e.g. "entertainment_EN" vs "entertainment_IN") so Tier 4 expansion queries can
  stay within the same geo-cultural space.

  Alternatively: move language/region filtering INTO resolvePeers() Levels 1-2
  (not just Level 3). Currently only Level 3 uses the rc clause.

  ───────────────────────────────────────────────────────────────────────────────
  ROOT CAUSE 5 — Format-type matching absent in Tier 3 scoring
  ─────────────────────────────────────────────────────────────────────────────
  A talk show (format=interview) and a comedy sketch channel (format=sketch)
  both have niche=entertainment. The phrase-based scoring rewards phrase overlap
  but doesn't penalise format mismatch enough (weight=0.21 is low).

  FIX: In buildPeersByContent, require format_type compatibility as a soft gate:
  channels with incompatible formats get multiplied by 0.5 unless phrase sim is
  very high (>0.4). Or add a "format cluster" map similar to NICHE_CLUSTERS.

  ───────────────────────────────────────────────────────────────────────────────
  PRIORITY RANKING:
    1. Root Cause 2 (NULL lang + IN region) — surgical, low risk, high impact
    2. Root Cause 1 (Tier 3 no lang filter) — highest impact, needs care for null-lang
    3. Root Cause 3 (language weight increase) — scoring-only, safe change
    4. Root Cause 4 (niche cluster geo-split) — medium scope
    5. Root Cause 5 (format weight/gate)      — low priority, niche-specific
`);

printDivider('─');
console.log('  Legend:  FP=false positive  PSim=phrase Jaccard similarity  Prec=precision');
console.log('           Lang/Rgn/Top/Fmt/Aud: ✓=match  ✗=mismatch  —=unknown\n');

